// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, address depositor) public {
        amount = bound(amount, 1, 1 ether);
        vm.assume(depositor != address(0));

        GreedyFallback bad = new GreedyFallback();

        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        vm.deal(address(bad), amount);
        vm.prank(address(bad));
        c.deposit{value: amount}();

        bool ok;
        try bad.callWithdraw(address(c)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract GreedyFallback {
    receive() external payable {
        for (uint i = 0; i < 1000; i++) {
            uint x = i * block.timestamp;
            x;
        }
    }

    function callWithdraw(address target) external {
        ReentrancyDAO(target).withdrawAll();
    }
}
